    w = int(g.get("grid_width", 0) or 0)
    h = int(g.get("grid_height", 0) or 0)

    def pos(v):
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("row", "col"), ("r", "c"), ("px", "py")):
                if a in v and b in v:
                    try:
                        return [int(v[a]), int(v[b])]
                    except:
                        pass
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return [int(v[0]), int(v[1])]
            except:
                pass
        return None

    s = pos(g.get("self_position")) or [0, 0]
    o = pos(g.get("opponent_position")) or [w // 2, h // 2]
    resources = g.get("resources") or []
    obstacles = {tuple(p) for p in (g.get("obstacles") or []) if pos(p)}
    sp = {tuple(p) for p in (g.get("self_path") or []) if pos(p)}
    op = {tuple(p) for p in (g.get("opponent_path") or []) if pos(p)}

    def pts(x):
        out = []
        if isinstance(x, dict):
            for v in x.values():
                p = pos(v)
                if p is not None:
                    out.append(p)
                elif isinstance(v, (list, tuple)):
                    for e in v:
                        p = pos(e)
                        if p is not None:
                            out.append(p)
        elif isinstance(x, (list, tuple)):
            for e in x:
                p = pos(e)
                if p is not None:
                    out.append(p)
        return out

    rs = pts(resources)
    best = None
    bd = 10**9
    for p in rs:
        d = abs(p[0] - s[0]) + abs(p[1] - s[1])
        if d < bd or (d == bd and (p[0], p[1]) < tuple(best or p)):
            bd = d
            best = p
    if best is None:
        best = [0 if s[0] > w // 2 else w - 1, 0 if s[1] > h // 2 else h - 1]

    dx = 0 if best[0] == s[0] else (1 if best[0] > s[0] else -1)
    dy = 0 if best[1] == s[1] else (1 if best[1] > s[1] else -1)

    cand = [(dx, dy), (dx, 0), (0, dy), (dx, -dy), (-dx, dy), (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]
    for mx, my in cand:
        nx, ny = s[0] + mx, s[1] + my
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles and (nx, ny) not in sp:
            if (nx, ny) not in op or abs(nx - o[0]) + abs(ny - o[1]) > 1:
                return [mx, my]
    return [0, 0]

